// Guard the door: bad input is rejected here, before it costs a single token.
// Bump PROMPT_VERSION whenever the prompt or model changes: cached answers from older versions are never reused.
const PROMPT_VERSION = 'v5-2026-10-25';
const MODEL = 'openai/gpt-4.1-mini (fallback google/gemini-2.5-flash)';
const b = $input.first().json.body || {};
const raw = (b.chatInput ?? b.question ?? '').toString();
const question = raw.replace(/\s+/g, ' ').trim();
const sessionId = (b.sessionId || 'anonymous').toString().replace(/[^A-Za-z0-9_-]/g, '').slice(0, 64) || 'anonymous';
const channel = ['dashboard', 'eval', 'api'].includes(b.channel) ? b.channel : 'dashboard';
const isArabic = /[؀-ۿ]/.test(question);
let reason = '', kind = '';
if (question.length < 3) { kind = 'input'; reason = 'The question is empty or too short.'; }
else if (question.length > 500) { kind = 'input'; reason = 'The question is too long (max 500 characters).'; }
// Privacy: a customer ID + a personal field is refused in code, so it never reaches the model (or its memory).
else if (/\bC\d{4,}\b/i.test(question) && /(name|phone|mobile|e-?mail|address|contact|اسم|تليفون|تلفون|موبايل|رقم|ايميل|إيميل|عنوان|تواصل)/i.test(question)) {
  kind = 'privacy';
  reason = isArabic
    ? 'مقدرش أدي بيانات شخصية عن عميل معين (اسم، تليفون، عنوان). أقدر أديك أرقام مجمّعة عن العملاء، زي عدد العملاء اللي بطّلوا يشتروا.'
    : 'I cannot share personal data about an individual customer (name, phone, address). I can give aggregated customer numbers instead, such as how many customers are dormant.';
}
return [{ json: {
  question, sessionId, channel, isArabic,
  valid: !reason, reason, kind,
  prompt_version: PROMPT_VERSION, model: MODEL,
  started_at: Date.now(),
  request_id: $execution.id
} }];

const c = $input.first().json;
return [{ json: {
  status: c.status, http_status: 200, answer: c.answer, value: c.value, unit: c.unit, period: c.period,
  grain: c.grain, source: c.source, sql: c.sql, why: c.why, grounded: c.grounded,
  ungrounded_numbers: c.ungrounded_numbers || [], kb_ids: c.kb_ids || [], tool_calls: 0,
  cached: true, cached_from: c.id
} }];

// One exit for every path (rejected, cached, answered, refused, error) = one response shape + one log row.
const v = $('Validate request').first().json;
const r = $input.first().json;
const latency_ms = Date.now() - v.started_at;
// "41.0% and 29.2%" already carries its unit: do not let the UI print "%%".
const unit = r.unit && String(r.value || '').trim().endsWith(r.unit) ? '' : (r.unit || '');
const response = {
  status: r.status, answer: r.answer || '', value: r.value || '', unit, period: r.period || '',
  grain: r.grain || '', source: r.source || '', sql: r.sql || '', why: r.why || '',
  grounded: r.grounded ?? null, warning: r.warning || '', cached: !!r.cached,
  evidence: r.evidence || (r.cached ? 'cache' : 'none'), retrieval: r.retrieval || null,
  tools_used: r.tools_used || [], kb_ids: r.kb_ids || [], latency_ms, request_id: v.request_id
};
const log = {
  session_id: v.sessionId, channel: v.channel, question: v.question || '(empty)', status: r.status,
  answer: response.answer, value: response.value, unit: response.unit, period: response.period,
  grain: response.grain, source: response.source, sql: response.sql, why: response.why,
  grounded: r.grounded ?? null, ungrounded_numbers: r.ungrounded_numbers || [], kb_ids: r.kb_ids || [],
  tool_calls: r.tool_calls || 0, model: r.cached || r.status === 'rejected' || v.kind === 'privacy' ? null : v.model,
  prompt_version: v.prompt_version,
  latency_ms, cached: !!r.cached, error: r.error || null,
  evidence: response.evidence, retrieval: response.retrieval, tools_used: response.tools_used
};
return [{ json: { http_status: r.http_status || 200, response, log } }];

// Rank-ordered context with stable ids so the model can cite [KB-n], trust rules first.
const v = $('Validate request').first().json;
let usedVector = true;
try { const e = $('Embed question (OpenRouter)').first().json; usedVector = !!(e.data && e.data[0]); } catch (err) { usedVector = false; }
const order = { trust_rule: 0, sql_example: 1, metric: 2, glossary: 3, finding: 4 };
const chunks = $input.all().map(i => i.json).filter(c => c && c.id != null)
  .sort((a, b) => (order[a.chunk_type] ?? 9) - (order[b.chunk_type] ?? 9) || b.score - a.score);
const context = chunks.map(c => {
  const va = c.metadata && c.metadata.verified_answer ? '\nverified_answer: ' + c.metadata.verified_answer : '';
  const topic = c.metadata && c.metadata.topic ? ' (topic: ' + c.metadata.topic + ')' : '';
  return '[KB-' + c.id + '] ' + c.chunk_type + topic + ' | ' + c.title + '\n' + c.content + va;
}).join('\n\n');
return [{ json: {
  question: v.question,
  sessionId: v.sessionId,
  // Decided in code from the question's script, so a refusal never switches language.
  reply_language: v.isArabic ? 'Egyptian Arabic (keep numbers in Western digits)' : 'English',
  context: context || 'No knowledge base entry matched. Use get_schema and run_sql, or refuse if the topic is not covered.',
  kb_ids: chunks.map(c => c.id),
  trust_hits: chunks.filter(c => c.chunk_type === 'trust_rule').map(c => c.id),
  retrieval: usedVector ? 'hybrid' : 'keyword_only'
} }];

