// Graceful failure: the user gets a clear message, the error goes to the log.
const v = $('Validate request').first().json;
const err = $input.first().json.error || $input.first().json;
return [{ json: {
  status: 'error', http_status: 200,
  answer: v.isArabic ? 'حصلت مشكلة مؤقتة وأنا بجهز الإجابة. جرّب تاني بعد دقيقة.' : 'Something went wrong while preparing the answer. Please try again in a minute.',
  error: (typeof err === 'string' ? err : (err.message || JSON.stringify(err))).slice(0, 1000),
  cached: false, grounded: null
} }];

// Bad input gets 400; a privacy request is a normal refusal (200), decided in code with zero tokens.
const v = $input.first().json;
if (v.kind === 'privacy') return [{ json: {
  status: 'refused', http_status: 200, answer: v.reason,
  why: v.isArabic ? 'حماية البيانات الشخصية للعملاء.' : 'Customer personal data is protected.',
  source: 'privacy rule (code)', evidence: 'trust_rule', grounded: true, cached: false
} }];
return [{ json: { status: 'rejected', http_status: 400, answer: v.reason, cached: false } }];

// Hallucination guard: every number in the answer must exist in the evidence
// (SQL tool results this turn + verified answers in the retrieved context + the user's own question).
const ctx = $('Build context').first().json;
const res = $input.first().json;
const out = res.output || {};
const steps = res.intermediateSteps || [];
const toText = x => typeof x === 'string' ? x : JSON.stringify(x);
const arabicDigits = s => String(s || '').replace(/[٠-٩]/g, d => String(d.charCodeAt(0) - 0x0660)).replace(/٫/g, '.').replace(/٬/g, ',');
// A number glued to a letter on its left is an identifier (customer C000123), not a quantity; 10.83x is still a number.
const nums = s => (arabicDigits(s).replace(/(\d),(?=\d{3})/g, '$1').match(/(?<![A-Za-z0-9_.])\d+(?:\.\d+)?/g) || []).map(Number);
const sqlSteps = steps.filter(s => s.action && s.action.tool === 'run_sql');
const evidence = nums(ctx.question + ' ' + ctx.context + ' ' + steps.map(s => toText(s.observation)).join(' '));
const isTrivial = n => Number.isInteger(n) && (n <= 31 || (n >= 1990 && n <= 2035));
const close = (a, e) => Math.abs(a - e) <= Math.max(Math.abs(e) * 0.006, 0.051);
const scales = [1, 100, 0.01, 1e-3, 1e-6, 1e-9];
const supported = a => evidence.some(e => scales.some(k => close(a, e * k)));
const claimed = [...new Set(nums((out.answer || '') + ' ' + (out.value || '')))].filter(n => !isTrivial(n));
const ungrounded = claimed.filter(n => !supported(n));
const inputOf = s => { const t = s.action.toolInput; return typeof t === 'string' ? t : (t && (t.sql || t.query)) || toText(t); };
const lastSql = sqlSteps.length ? inputOf(sqlSteps[sqlSteps.length - 1]) : '';
const grounded = ungrounded.length === 0;
const refused = out.status === 'refused';
const base = {
  http_status: 200, kb_ids: ctx.kb_ids, retrieval: ctx.retrieval, tool_calls: steps.length,
  tools_used: [...new Set(steps.map(s => s.action && s.action.tool).filter(Boolean))],
  grounded, ungrounded_numbers: ungrounded.map(String), cached: false
};
// No SQL ran and the numbers are not in the evidence: the model is replaying memory or guessing. Never show it.
if (!refused && !grounded && sqlSteps.length === 0) {
  const ar = /[؀-ۿ]/.test(ctx.question);
  return [{ json: { ...base,
    status: 'error', evidence: 'none', sql: '',
    answer: ar ? 'مقدرتش أتأكد من الأرقام دي من الداتا، فمش هعرضها. جرّب تسأل السؤال تاني بصيغة أوضح.' : 'I could not verify these numbers against the data, so I will not show them. Please rephrase the question and try again.',
    error: 'blocked_ungrounded_no_sql: ' + String(out.answer || '').slice(0, 800)
  } }];
}
return [{ json: { ...base,
  status: refused ? 'refused' : 'answered',
  answer: out.answer || '',
  value: out.value || '', unit: out.unit || '', period: out.period || '', grain: out.grain || '',
  source: out.source || '',
  // Only SQL that really ran is reported: the model cannot claim a query it did not execute.
  sql: lastSql, why: out.why || '',
  evidence: refused ? 'trust_rule' : (sqlSteps.length ? 'live_sql' : (claimed.length ? 'kb_only' : 'none')),
  warning: grounded ? '' : 'Some numbers could not be traced to a query result. Please verify before using them.'
} }];
